:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #eaeaea;
  --text-dim: #a0a0b0;
  --pixel-border: 4px solid var(--primary);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg);
  background-image: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(255, 255, 255, 0.03) 2px,
    rgba(255, 255, 255, 0.03) 4px
  );
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background-color: var(--card-bg);
  border: var(--pixel-border);
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  font-size: 1.6rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--primary);
  text-shadow: 2px 2px 0 rgba(0, 0, 0, 0.5);
}

.timer-display {
  font-size: 4.5rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 4px;
  color: var(--text);
  text-shadow: 3px 3px 0 var(--secondary);
  padding: 8px 0;
}

.mode-indicator {
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: var(--text-dim);
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 600;
  padding: 12px 28px;
  border: 3px solid var(--primary);
  background-color: var(--secondary);
  color: var(--text);
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: background-color 0.1s, transform 0.05s, box-shadow 0.05s;
  box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.4);
}

.btn:hover {
  background-color: var(--primary);
  color: var(--bg);
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 rgba(0, 0, 0, 0.4);
}

.mode-switch {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  margin-top: 8px;
}

.mode-btn {
  font-size: 0.95rem;
  padding: 8px 16px;
  border-color: var(--text-dim);
  background-color: transparent;
  color: var(--text-dim);
  box-shadow: none;
}

.mode-btn:hover {
  background-color: var(--secondary);
  color: var(--text);
  border-color: var(--text-dim);
}

.mode-btn.active {
  border-color: var(--primary);
  color: var(--primary);
  background-color: rgba(233, 69, 96, 0.1);
}

@media (max-width: 400px) {
  .timer-display {
    font-size: 3.2rem;
    letter-spacing: 2px;
  }
  .btn {
    padding: 10px 18px;
    font-size: 1rem;
  }
  .card {
    padding: 24px 16px;
  }
}

(function () {
  'use strict';

  const WORK_TIME = 25 * 60;
  const BREAK_TIME = 5 * 60;

  let mode = 'work';
  let timeLeft = WORK_TIME;
  let timerId = null;
  let isRunning = false;

  const timerDisplay = document.getElementById('timerDisplay');
  const modeIndicator = document.getElementById('modeIndicator');
  const startPauseBtn = document.getElementById('startPauseBtn');
  const resetBtn = document.getElementById('resetBtn');
  const workBtn = document.getElementById('workBtn');
  const breakBtn = document.getElementById('breakBtn');

  function formatTime(seconds) {
    const m = Math.floor(seconds / 60).toString().padStart(2, '0');
    const s = (seconds % 60).toString().padStart(2, '0');
    return m + ':' + s;
  }

  function updateDisplay() {
    timerDisplay.textContent = formatTime(timeLeft);
    modeIndicator.textContent = mode === 'work' ? 'Work' : 'Break';
    startPauseBtn.textContent = isRunning ? 'Pause' : 'Start';
    startPauseBtn.setAttribute('aria-label', isRunning ? 'Pause timer' : 'Start timer');
  }

  function stopTimer() {
    if (timerId !== null) {
      clearInterval(timerId);
      timerId = null;
    }
    isRunning = false;
  }

  function tick() {
    timeLeft -= 1;
    if (timeLeft <= 0) {
      stopTimer();
      timeLeft = 0;
      updateDisplay();
      // Auto-switch mode after completion
      if (mode === 'work') {
        setMode('break');
      } else {
        setMode('work');
      }
      return;
    }
    updateDisplay();
  }

  function startTimer() {
    if (isRunning) return;
    isRunning = true;
    timerId = setInterval(tick, 1000);
    updateDisplay();
  }

  function pauseTimer() {
    stopTimer();
    updateDisplay();
  }

  function resetTimer() {
    stopTimer();
    timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
    updateDisplay();
  }

  function setMode(newMode) {
    stopTimer();
    mode = newMode;
    timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
    updateDisplay();
    workBtn.classList.toggle('active', mode === 'work');
    breakBtn.classList.toggle('active', mode === 'break');
  }

  startPauseBtn.addEventListener('click', function () {
    if (isRunning) {
      pauseTimer();
    } else {
      startTimer();
    }
  });

  resetBtn.addEventListener('click', resetTimer);

  workBtn.addEventListener('click', function () {
    setMode('work');
  });

  breakBtn.addEventListener('click', function () {
    setMode('break');
  });

  // Initialize
  setMode('work');
})();
